/**
 * Cartesia AI Text-to-Speech client.
 * Speech is generated by the backend so the API key and locked voice
 * configuration never ship to the browser.
 *
 * Progressive playback: first chunk plays ASAP; remaining chunks queue;
 * finished narration is persisted server-side for instant replay.
 */
import { API_BASE_URL } from './api'

/** Must match server/config/cartesia.js CARTESIA_LIMITS.chunkSize */
export const TTS_CHUNK_SIZE = 4500

const audioCache = new Map()
const chunkCache = new Map()
const inflightPromises = new Map()
const inflightChunks = new Map()

/**
 * Strips HTML tags, Markdown links, and excess whitespace to produce clean speech text.
 */
export function cleanTextForSpeech(rawText = '') {
  if (!rawText) return ''
  return rawText
    .replace(/<[^>]*>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/https?:\/\/\S+/g, '')
    .replace(/—|–/g, ', ')
    .replace(/\s+/g, ' ')
    .trim()
}

/**
 * Prepares the complete spoken narrative for an article
 */
export function buildArticleNarrationText(article) {
  if (!article) return ''

  const parts = []

  if (article.title) {
    parts.push(cleanTextForSpeech(article.title) + '.')
  }

  if (article.quote) {
    parts.push(cleanTextForSpeech(article.quote))
  }

  if (Array.isArray(article.paragraphs) && article.paragraphs.length > 0) {
    article.paragraphs.forEach((p) => {
      const cleaned = cleanTextForSpeech(p)
      if (cleaned) parts.push(cleaned)
    })
  } else if (article.contentHtml) {
    const cleaned = cleanTextForSpeech(article.contentHtml)
    if (cleaned) parts.push(cleaned)
  } else if (article.excerpt) {
    const cleaned = cleanTextForSpeech(article.excerpt)
    if (cleaned) parts.push(cleaned)
  }

  return parts.join(' ')
}

function splitOversizedSentence(sentence, maxChunkSize) {
  const words = sentence.split(/\s+/).filter(Boolean)
  const parts = []
  let current = ''
  for (const word of words) {
    const next = current ? `${current} ${word}` : word
    if (next.length <= maxChunkSize) {
      current = next
    } else {
      if (current) parts.push(current)
      current = word.length <= maxChunkSize ? word : word.slice(0, maxChunkSize)
    }
  }
  if (current) parts.push(current)
  return parts
}

/** Mirror of server splitTextIntoChunks so progressive indices stay aligned. */
export function splitTextIntoChunks(text, maxChunkSize = TTS_CHUNK_SIZE) {
  const clean = cleanTextForSpeech(text)
  if (!clean) return []
  if (clean.length <= maxChunkSize) return [clean]

  const sentences = clean.match(/[^.!?]+[.!?]+|\S+$/g) || [clean]
  const chunks = []
  let currentChunk = ''

  for (const sentence of sentences) {
    const next = (currentChunk + ' ' + sentence).trim()
    if (next.length <= maxChunkSize) {
      currentChunk = next
    } else {
      if (currentChunk) chunks.push(currentChunk)
      if (sentence.trim().length <= maxChunkSize) {
        currentChunk = sentence.trim()
      } else {
        const parts = splitOversizedSentence(sentence.trim(), maxChunkSize)
        chunks.push(...parts.slice(0, -1))
        currentChunk = parts[parts.length - 1] || ''
      }
    }
  }
  if (currentChunk) chunks.push(currentChunk)
  return chunks
}

export async function hashTranscript(text) {
  const clean = cleanTextForSpeech(text)
  if (!clean) return ''
  if (typeof crypto !== 'undefined' && crypto.subtle) {
    const data = new TextEncoder().encode(clean)
    const digest = await crypto.subtle.digest('SHA-256', data)
    return Array.from(new Uint8Array(digest))
      .map((b) => b.toString(16).padStart(2, '0'))
      .join('')
  }
  // Fallback: non-crypto fingerprint (rare browsers)
  let h = 0
  for (let i = 0; i < clean.length; i += 1) {
    h = (Math.imul(31, h) + clean.charCodeAt(i)) | 0
  }
  return `fallback_${Math.abs(h)}_${clean.length}`
}

async function readErrorMessage(response) {
  const fallback = 'Failed to generate voice narration. Please try again.'
  const contentType = response.headers.get('content-type') || ''
  try {
    if (contentType.includes('application/json')) {
      const data = await response.json()
      return data.error || fallback
    }
    const text = await response.text()
    return text || fallback
  } catch {
    return fallback
  }
}

async function blobFromResponse(response) {
  const contentType = response.headers.get('content-type') || ''
  if (contentType.includes('application/json')) {
    const data = await response.json()
    if (data.audioUrl) {
      return { audioUrl: data.audioUrl, fromJson: true, hash: data.hash }
    }
    throw new Error(data.error || 'Failed to generate voice narration. Please try again.')
  }

  const audioBlob = await response.blob()
  if (!audioBlob || audioBlob.size === 0) {
    throw new Error('Voice service returned empty audio. Please try again.')
  }
  const typedBlob =
    audioBlob.type && audioBlob.type.startsWith('audio/')
      ? audioBlob
      : new Blob([audioBlob], { type: 'audio/mpeg' })
  return { blob: typedBlob, fromJson: false }
}

function cacheFullAudio(cacheKey, audioUrl) {
  audioCache.set(cacheKey, audioUrl)
}

/**
 * Look up durable/server-cached full narration.
 * @returns {Promise<{ audioUrl: string, cached: boolean, hash: string } | null>}
 */
export async function getCachedCartesiaSpeech({ articleId, hash, text }) {
  const resolvedHash = hash || (text ? await hashTranscript(text) : '')
  if (!resolvedHash) return null

  const cacheKey = articleId ? String(articleId) : resolvedHash
  if (audioCache.has(cacheKey)) {
    return { audioUrl: audioCache.get(cacheKey), cached: true, hash: resolvedHash }
  }

  const params = new URLSearchParams({ hash: resolvedHash })
  if (articleId) params.set('articleId', articleId)

  try {
    const response = await fetch(`${API_BASE_URL}/tts/cached?${params.toString()}`, {
      method: 'GET',
    })
    if (response.status === 404) return null
    if (!response.ok) return null

    const parsed = await blobFromResponse(response)
    if (parsed.fromJson && parsed.audioUrl) {
      cacheFullAudio(cacheKey, parsed.audioUrl)
      return { audioUrl: parsed.audioUrl, cached: true, hash: resolvedHash }
    }
    const audioUrl = URL.createObjectURL(parsed.blob)
    cacheFullAudio(cacheKey, audioUrl)
    return { audioUrl, cached: true, hash: resolvedHash }
  } catch (err) {
    console.debug('TTS cache lookup failed:', err)
    return null
  }
}

/**
 * Persist finished progressive narration (reuses server chunk buffers when present).
 */
export async function finalizeCartesiaSpeechCache({ articleId, hash, text, chunks }) {
  const resolvedHash = hash || (text ? await hashTranscript(text) : '')
  const resolvedChunks = chunks?.length ? chunks : splitTextIntoChunks(text)
  if (!resolvedHash || !resolvedChunks.length) return null

  try {
    const response = await fetch(`${API_BASE_URL}/tts/cached`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        articleId: articleId || '',
        hash: resolvedHash,
        text: cleanTextForSpeech(text || ''),
        chunks: resolvedChunks,
      }),
    })
    if (!response.ok) {
      console.debug('TTS finalize failed:', await readErrorMessage(response))
      return null
    }

    const contentType = response.headers.get('content-type') || ''
    if (contentType.includes('application/json')) {
      const data = await response.json()
      if (data.audioUrl) {
        const cacheKey = articleId ? String(articleId) : resolvedHash
        cacheFullAudio(cacheKey, data.audioUrl)
        return { audioUrl: data.audioUrl, hash: resolvedHash, cached: true }
      }
    }
    return { hash: resolvedHash, cached: true }
  } catch (err) {
    console.debug('TTS finalize error:', err)
    return null
  }
}

/**
 * Requests a single speech chunk for progressive playback.
 */
export async function generateCartesiaSpeechChunk({ text, chunkIndex = 0, articleId }) {
  const cleanTranscript = cleanTextForSpeech(text)
  if (!cleanTranscript) {
    throw new Error('No readable text available to narrate.')
  }

  const cacheKey = `${articleId || 'article'}:chunk:${chunkIndex}:${cleanTranscript.slice(0, 48)}`
  if (chunkCache.has(cacheKey)) {
    return { audioUrl: chunkCache.get(cacheKey), cached: true, chunkIndex }
  }
  if (inflightChunks.has(cacheKey)) {
    return inflightChunks.get(cacheKey)
  }

  const fetchPromise = (async () => {
    try {
      const controller = new AbortController()
      const timeoutId = setTimeout(() => controller.abort(), 60000)
      let response
      try {
        response = await fetch(`${API_BASE_URL}/tts/speech-chunk`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ text: cleanTranscript, chunkIndex }),
          signal: controller.signal,
        })
      } catch (err) {
        if (err.name === 'AbortError') {
          throw new Error('Voice generation timed out. Please try again.')
        }
        throw new Error('Unable to reach the voice service. Please check your connection.')
      } finally {
        clearTimeout(timeoutId)
      }

      if (!response.ok) {
        throw new Error(await readErrorMessage(response))
      }

      const parsed = await blobFromResponse(response)
      const audioUrl = parsed.fromJson
        ? parsed.audioUrl
        : URL.createObjectURL(parsed.blob)
      chunkCache.set(cacheKey, audioUrl)
      return { audioUrl, cached: false, chunkIndex }
    } finally {
      inflightChunks.delete(cacheKey)
    }
  })()

  inflightChunks.set(cacheKey, fetchPromise)
  return fetchPromise
}

/**
 * Full-article synthesis (fallback / short articles).
 */
export async function generateCartesiaSpeech({ text, articleId }) {
  const cleanTranscript = cleanTextForSpeech(text)
  if (!cleanTranscript) {
    throw new Error('No readable text available to narrate.')
  }

  const cacheKey = articleId ? String(articleId) : cleanTranscript.slice(0, 80)

  if (audioCache.has(cacheKey)) {
    return {
      audioUrl: audioCache.get(cacheKey),
      cached: true,
    }
  }

  if (inflightPromises.has(cacheKey)) {
    return inflightPromises.get(cacheKey)
  }

  const fetchPromise = (async () => {
    try {
      const hash = await hashTranscript(cleanTranscript)
      const cached = await getCachedCartesiaSpeech({ articleId, hash })
      if (cached?.audioUrl) {
        return { audioUrl: cached.audioUrl, cached: true, hash }
      }

      const controller = new AbortController()
      const timeoutId = setTimeout(() => controller.abort(), 180000)

      let response
      try {
        response = await fetch(`${API_BASE_URL}/tts/speech`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ text: cleanTranscript }),
          signal: controller.signal,
        })
      } catch (err) {
        if (err.name === 'AbortError') {
          throw new Error('Voice generation timed out. Please try again.')
        }
        throw new Error('Unable to reach the voice service. Please check your connection.')
      } finally {
        clearTimeout(timeoutId)
      }

      if (!response.ok) {
        throw new Error(await readErrorMessage(response))
      }

      const parsed = await blobFromResponse(response)
      const audioUrl = parsed.fromJson
        ? parsed.audioUrl
        : URL.createObjectURL(parsed.blob)
      cacheFullAudio(cacheKey, audioUrl)

      return {
        audioUrl,
        cached: false,
        hash,
      }
    } finally {
      inflightPromises.delete(cacheKey)
    }
  })()

  inflightPromises.set(cacheKey, fetchPromise)
  return fetchPromise
}

/**
 * Prefetch only the first chunk so Listen can start almost immediately.
 */
export function prefetchCartesiaSpeechChunk0({ text, articleId }) {
  if (!text) return Promise.resolve(null)
  const chunks = splitTextIntoChunks(text)
  if (!chunks.length) return Promise.resolve(null)
  return generateCartesiaSpeechChunk({
    text: chunks[0],
    chunkIndex: 0,
    articleId,
  })
    .then((res) => res?.audioUrl || null)
    .catch((err) => {
      console.debug('Background chunk-0 prefetch idle:', err)
      return null
    })
}

/**
 * @deprecated Prefer prefetchCartesiaSpeechChunk0 for warm-start without full cost.
 * Kept for compatibility; now warms chunk 0 only.
 */
export function prefetchCartesiaSpeech({ text, articleId }) {
  return prefetchCartesiaSpeechChunk0({ text, articleId })
}
